84	     * Required national-number length keyed by E.164 country calling code: a
85	     * {@code '+61'} (Australia) number carries 9 national digits and a {@code '+1'}
86	     * (NANP) number carries 10. A number whose country code is listed here must have
87	     * exactly the mandated number of national digits.
88	     */
89	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
90	        Map.of("61", 9, "1", 10);
91	
92	    /**
93	     * Inclusive 4-digit postcode range {@code {low, high}} keyed by the region derived
94	     * from the owner's city (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city whose
95	     * region is not listed here (see {@link OwnerMapper#CITY_REGION}) accepts any 4-digit
96	     * postcode.
97	     */
98	    private static final Map<String, int[]> REGION_POSTCODE_RANGES =
99	        Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099},
100	            "QLD", new int[] {4000, 4099});
101	
