110	    public OwnerRestControllerV1(ClinicService clinicService,
111	                                 OwnerMapper ownerMapper,
112	                                 PetMapper petMapper,
113	                                 VisitMapper visitMapper) {
114	        this.clinicService = clinicService;
115	        this.ownerMapper = ownerMapper;
116	        this.petMapper = petMapper;
117	        this.visitMapper = visitMapper;
