136	    @Override
137	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
138	        Owner owner = this.clinicService.findOwnerById(ownerId);
139	        if (owner == null) {
140	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
141	        }
142	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Override
147	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
148	        // Validate & normalize the optional email; reject the create when it is present but invalid.
149	        if (!normalizeEmail(ownerFieldsDto)) {
150	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
151	        }
152	        // Validate & normalize the optional postcode; reject the create when it is present but
153	        // not valid for the owner's city (see normalizePostcode).
154	        if (!normalizePostcode(ownerFieldsDto)) {
155	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
156	        }
157	        // Normalize the required address (trim/collapse whitespace, upper-case, expand
158	        // abbreviations) and store the normalized form back on the DTO so it is what gets
159	        // persisted and compared. Reject the create when the address is blank once normalized.
160	        String canonicalAddress = normalizeAddress(ownerFieldsDto.getAddress());
161	        if (canonicalAddress.isBlank()) {
162	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
163	        }
164	        ownerFieldsDto.setAddress(canonicalAddress);
165	        // Reject the create when the owner's city is already at capacity, i.e. it already
166	        // contains 50 or more owners (compared case-insensitively).
167	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
168	            return new ResponseEntity<>(HttpStatus.CONFLICT);
169	        }
170	        // Normalize the telephone to E.164; reject the create when it cannot form a valid number.
171	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
172	        if (normalizedTelephone == null) {
173	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
174	        }
175	        ownerFieldsDto.setTelephone(normalizedTelephone);
176	        // Consolidated duplicate detection. All former separate telephone, email and household
177	        // duplicate checks are now expressed through the single derived identity key
178	        // '<normalizedTelephone>|<email or empty>|<householdId>' (see OwnerMapper#identityKey).
179	        // A create is rejected only when the new owner's identity collides with an existing owner's.
180	        // Because the telephone is part of the identity, two members of the same household with
181	        // different telephones no longer collide and are both allowed; only owners that share the
182	        // same normalized telephone and email are treated as the same identity.
183	        Owner candidate = ownerMapper.toOwner(ownerFieldsDto);
184	        String contactIdentity = identityContact(candidate);
185	        boolean identityInUse = this.clinicService.findAllOwners().stream()
186	            .anyMatch(existing -> contactIdentity.equals(identityContact(existing)));
187	        if (identityInUse) {
188	            return new ResponseEntity<>(HttpStatus.CONFLICT);
189	        }
190	        // Determine the effective registration date — the value supplied on the request, or the
191	        // server's current date when none was supplied — and roll it forward to the next business
192	        // day: a Saturday or Sunday moves to the following Monday. Everything derived from the
193	        // registration date (membership-number year segment, per-day create-limit) uses this
194	        // adjusted date.
195	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
196	        if (registrationDate == null) {
197	            registrationDate = LocalDate.now();
198	        }
199	        // Reject a supplied registration date that lies in the future (later than the
200	        // server's current date): an owner cannot be registered ahead of time.
201	        else if (registrationDate.isAfter(LocalDate.now())) {
202	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
203	        }
204	        registrationDate = toBusinessDay(registrationDate);
205	        // Reject the create when the daily sign-up limit has been reached, i.e. 100 or more
206	        // owners have already been registered on this (adjusted) business day.
207	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
208	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
209	        }
210	        HttpHeaders headers = new HttpHeaders();
211	        Owner owner = candidate;
212	        owner.setRegistrationDate(registrationDate);
213	        // Assign the customer code as '<REGION>-<HASH8>': the region derived from the owner's
214	        // postcode (falling back to the city, then 'UNKNOWN') and the first 8 upper-case hex
215	        // characters of the SHA-256 of the normalized telephone concatenated with the last name.
216	        owner.setCustomerCode(customerCode(owner));
217	        // Record how many existing owners already share this owner's first and last name
218	        // (compared case-insensitively) at the moment before this owner is created.
219	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
220	        // Flag a bulk sign-up when more than 80 owners have already been created today, i.e.
221	        // registered on this (adjusted) business day before this owner is created.
222	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > 80);
223	        // Record the size of this owner's household after this create: the number of existing
224	        // owners sharing the same household (matching last name and address) plus this owner.
225	        owner.setHouseholdSize(countHouseholdMembers(owner.getLastName(), owner.getAddress()) + 1);
226	        this.clinicService.saveOwner(owner);
227	        // Emit an audit line recording the new owner's id, customer code, registration date
228	        // and membership level.
229	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
230	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
231	            ownerMapper.membershipLevel(owner));
232	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
233	        headers.setLocation(UriComponentsBuilder.newInstance()
234	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
235	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
236	    }
237	
238	    /**
239	     * Validate and normalize the optional owner email in place.
240	     *
241	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
242	     * When present it must be a syntactically valid address; a valid address is
243	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
244	     * present but syntactically invalid, so the caller can reject with 400.
245	     */
246	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
247	        String email = ownerFieldsDto.getEmail();
248	        if (email == null || email.isBlank()) {
249	            ownerFieldsDto.setEmail(null);
250	            return true;
251	        }
252	        String normalized = email.trim().toLowerCase(Locale.ROOT);
253	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
254	            return false;
255	        }
256	        ownerFieldsDto.setEmail(normalized);
257	        return true;
258	    }
259	
260	    /**
261	     * Validate the optional owner postcode in place.
262	     *
263	     * <p>An absent (or blank) postcode is allowed and is normalized to {@code null}.
264	     * When present it must be exactly 4 digits, and — when the owner's city maps to a
265	     * known region via {@link OwnerMapper#CITY_REGION} — it must fall within that
266	     * region's inclusive postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
267	     * A city with no known region accepts any 4-digit postcode. Returns {@code false}
268	     * when a postcode is present but malformed or out of range, so the caller can
269	     * reject with 400.
270	     */
271	    private boolean normalizePostcode(OwnerFieldsDto ownerFieldsDto) {
272	        String postcode = ownerFieldsDto.getPostcode();
273	        if (postcode == null || postcode.isBlank()) {
274	            ownerFieldsDto.setPostcode(null);
275	            return true;
276	        }
277	        if (!postcode.matches("\\d{4}")) {
278	            return false;
279	        }
280	        String region = OwnerMapper.CITY_REGION.get(ownerFieldsDto.getCity());
281	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
282	        if (range != null) {
283	            int value = Integer.parseInt(postcode);
284	            if (value < range[0] || value > range[1]) {
285	                return false;
286	            }
287	        }
288	        return true;
289	    }
290	
291	    /**
292	     * Normalize an owner address: trim, collapse each run of whitespace to a single
293	     * space, upper-case, and expand common street-type abbreviations
294	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
295	     * A {@code null} value normalizes to the empty string.
296	     */
297	    private static String normalizeAddress(String value) {
298	        if (value == null) {
299	            return "";
300	        }
301	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
302	        if (collapsed.isEmpty()) {
303	            return "";
304	        }
305	        String[] tokens = collapsed.split(" ");
306	        StringBuilder sb = new StringBuilder(collapsed.length());
307	        for (int i = 0; i < tokens.length; i++) {
308	            if (i > 0) {
309	                sb.append(' ');
310	            }
311	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
312	        }
313	        return sb.toString();
314	    }
315	
316	    /**
317	     * The contact portion of an owner's derived identity key: its normalized telephone and
318	     * email ('&lt;normalizedTelephone&gt;|&lt;email or empty&gt;'), i.e. the identity key
319	     * without the household segment. Two owners share an identity when this value is equal;
320	     * because the telephone is part of it, members of one household with different telephones
321	     * do not collide. A {@code null} email contributes the empty string.
322	     */
323	    private static String identityContact(Owner owner) {
324	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
325	        String email = owner.getEmail() == null ? "" : owner.getEmail();
326	        return telephone + "|" + email;
327	    }
328	
329	    /**
330	     * Normalize an owner household field (last name or address) for duplicate detection:
331	     * trimmed, lower-cased and with all runs of whitespace collapsed to a single space.
332	     * A {@code null} value normalizes to the empty string.
333	     */
334	    private static String normalizeHouseholdKey(String value) {
335	        if (value == null) {
336	            return "";
337	        }
338	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
339	    }
340	
341	    /**
342	     * Normalize a telephone number to E.164 form.
343	     *
344	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
345	     * explicit leading {@code '+'} and country code it is kept; otherwise the
346	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
347	     * dropped from the national digits. The result must contain 8 to 15 digits
348	     * after the {@code '+'}, and — for a recognised country calling code — exactly
349	     * the national-number length that code mandates ({@code '+61'} => 9 national
350	     * digits, {@code '+1'} => 10).
351	     *
352	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
353	     *         the input is absent or cannot form a valid E.164 number.
354	     */
355	    private static String toE164(String raw) {
356	        if (raw == null) {
357	            return null;
358	        }
359	        String trimmed = raw.trim();
360	        boolean hasCountryCode = trimmed.startsWith("+");
361	        // Strip spaces, dashes and brackets.
362	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
363	        String digits;
364	        if (hasCountryCode) {
365	            // Keep the explicit country code; drop the leading '+' for validation.
366	            digits = stripped.substring(1);
367	        } else {
368	            // No country code: assume '+61' and drop a single leading '0'.
369	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
370	            digits = "61" + national;
371	        }
372	        if (!digits.matches("\\d{8,15}")) {
373	            return null;
374	        }
375	        // For a recognised country calling code, enforce the exact national-number length it
376	        // mandates (e.g. '+61' => 9 national digits, '+1' => 10). Longer codes win so a '+61'
377	        // number is not mistaken for a '+6...' one. Unknown codes keep the generic 8-15 rule.
378	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet().stream()
379	                .sorted((a, b) -> b.length() - a.length()).toList()) {
380	            if (digits.startsWith(countryCode)) {
381	                int nationalLength = digits.length() - countryCode.length();
382	                if (nationalLength != NATIONAL_NUMBER_LENGTHS.get(countryCode)) {
383	                    return null;
384	                }
385	                break;
386	            }
387	        }
388	        return "+" + digits;
389	    }
390	
391	    /**
392	     * Count the existing owners whose first and last name match the given names,
393	     * compared case-insensitively. Used to record an owner's namesake count at the
394	     * moment before it is created.
395	     */
396	    private int countNamesakes(String firstName, String lastName) {
397	        return (int) this.clinicService.findAllOwners().stream()
398	            .filter(existing -> existing.getFirstName() != null
399	                && existing.getFirstName().equalsIgnoreCase(firstName)
400	                && existing.getLastName() != null
401	                && existing.getLastName().equalsIgnoreCase(lastName))
402	            .count();
403	    }
404	
405	    /**
406	     * Count the existing owners in the same household as the given last name and address
407	     * (compared after household-key normalization). Used, together with the owner being
408	     * created, to derive the household size recorded on the owner.
409	     */
410	    private int countHouseholdMembers(String lastName, String address) {
411	        String normalizedLastName = normalizeHouseholdKey(lastName);
412	        String normalizedAddress = normalizeHouseholdKey(address);
413	        return (int) this.clinicService.findAllOwners().stream()
414	            .filter(existing ->
415	                normalizeHouseholdKey(existing.getLastName()).equals(normalizedLastName)
416	                    && normalizeHouseholdKey(existing.getAddress()).equals(normalizedAddress))
417	            .count();
418	    }
419	
420	    /**
421	     * Build the owner's customer code, formatted {@code '<REGION>-<HASH8>'}.
422	     *
423	     * <p>{@code REGION} is the region derived from the owner's postcode (see
424	     * {@link #deriveRegion}). {@code HASH8} is the first 8 upper-case hex characters of the
425	     * SHA-256 of the normalized telephone concatenated with the last name
426	     * (e.g. {@code 'NSW-1A2B3C4D'}).
427	     */
428	    private String customerCode(Owner owner) {
429	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
430	        String hash8 = sha256HexUpper(owner.getTelephone() + owner.getLastName(), 8);
431	        return region + "-" + hash8;
432	    }
433	
434	    /**
435	     * Derive the owner's region, preferring the postcode. The postcode is matched against
436	     * each region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); only when
437	     * it is absent or in no known range does this fall back to the fixed city-to-region table
438	     * (see {@link OwnerMapper#CITY_REGION}), and finally {@code 'UNKNOWN'}.
439	     */
440	    private static String deriveRegion(String postcode, String city) {
441	        if (postcode != null && postcode.matches("\\d{4}")) {
442	            int value = Integer.parseInt(postcode);
443	            for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
444	                int[] range = entry.getValue();
445	                if (value >= range[0] && value <= range[1]) {
446	                    return entry.getKey();
447	                }
448	            }
449	        }
450	        return OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
451	    }
452	
453	    /**
454	     * The first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
455	     * bytes of {@code value}.
456	     */
457	    private static String sha256HexUpper(String value, int length) {
458	        try {
459	            byte[] digest = MessageDigest.getInstance("SHA-256")
460	                .digest(value.getBytes(StandardCharsets.UTF_8));
461	            StringBuilder sb = new StringBuilder(digest.length * 2);
462	            for (byte b : digest) {
463	                sb.append(String.format("%02X", b));
464	            }
465	            return sb.substring(0, length);
466	        }
467	        catch (NoSuchAlgorithmException e) {
468	            throw new IllegalStateException(e);
469	        }
470	    }
471	
472	    /**
473	     * Count the existing owners located in the given city, compared case-insensitively.
474	     * Used to derive the per-city 4-digit sequence in the customer code.
475	     */
476	    private int countOwnersInCity(String city) {
477	        return (int) this.clinicService.findAllOwners().stream()
478	            .filter(existing -> existing.getCity() != null
479	                && existing.getCity().equalsIgnoreCase(city))
480	            .count();
481	    }
482	
483	    /**
484	     * Count the existing owners whose registration date is the given (adjusted business) date.
485	     * Used to enforce the per-day sign-up limit.
486	     */
487	    private int countOwnersRegisteredOn(LocalDate date) {
488	        return (int) this.clinicService.findAllOwners().stream()
489	            .filter(existing -> date.equals(existing.getRegistrationDate()))
490	            .count();
491	    }
492	
493	    /**
494	     * Roll a registration date forward onto a business day: a Saturday or Sunday is moved to
495	     * the following Monday; a weekday is returned unchanged.
496	     */
497	    private static LocalDate toBusinessDay(LocalDate date) {
498	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
499	            || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
500	            date = date.plusDays(1);
501	        }
502	        return date;
503	    }
504	
505	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
506	    @Override
507	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
508	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
509	        if (currentOwner == null) {
510	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
511	        }
512	        if (!normalizeEmail(ownerFieldsDto)) {
513	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
514	        }
515	        if (!normalizePostcode(ownerFieldsDto)) {
516	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
517	        }
518	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
519	        if (normalizedTelephone == null) {
520	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
521	        }
522	        currentOwner.setAddress(ownerFieldsDto.getAddress());
523	        currentOwner.setCity(ownerFieldsDto.getCity());
524	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
525	        currentOwner.setLastName(ownerFieldsDto.getLastName());
526	        currentOwner.setTelephone(normalizedTelephone);
527	        currentOwner.setEmail(ownerFieldsDto.getEmail());
528	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
529	        this.clinicService.saveOwner(currentOwner);
530	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
531	    }
532	
533	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
534	    @Transactional
535	    @Override
536	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
537	        Owner owner = this.clinicService.findOwnerById(ownerId);
538	        if (owner == null) {
539	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
540	        }
541	        this.clinicService.deleteOwner(owner);
542	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
543	    }
544	
545	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
546	    @Override
547	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
548	        Owner owner = this.clinicService.findOwnerById(ownerId);
549	        if (owner == null) {
550	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
551	        }
552	        HttpHeaders headers = new HttpHeaders();
553	        Pet pet = petMapper.toPet(petFieldsDto);
554	        owner.setId(ownerId);
555	        pet.setOwner(owner);
556	        pet.getType().setName(null);
557	        this.clinicService.savePet(pet);
558	        PetDto petDto = petMapper.toPetDto(pet);
559	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
560	            .buildAndExpand(pet.getId()).toUri());
561	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
562	    }
563	
564	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
565	    @Override
566	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
567	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
568	        if (currentOwner != null) {
569	            Pet currentPet = this.clinicService.findPetById(petId);
570	            if (currentPet != null) {
571	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
572	                currentPet.setName(petFieldsDto.getName());
573	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
574	                this.clinicService.savePet(currentPet);
575	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
576	            }
577	        }
578	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
579	    }
580	
581	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
582	    @Override
583	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
584	        HttpHeaders headers = new HttpHeaders();
585	        Visit visit = visitMapper.toVisit(visitFieldsDto);
586	        Pet pet = new Pet();
587	        pet.setId(petId);
588	        visit.setPet(pet);
589	        this.clinicService.saveVisit(visit);
590	        VisitDto visitDto = visitMapper.toVisitDto(visit);
591	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
592	            .buildAndExpand(visit.getId()).toUri());
593	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
594	    }
595	
596	
597	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
598	    @Override
599	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
600	        Owner owner = this.clinicService.findOwnerById(ownerId);
601	        if (owner != null) {
602	            Pet pet = owner.getPet(petId);
603	            if (pet != null) {
604	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
605	            }
606	        }
607	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
608	    }
609	}
