42	     * otherwise 'PHONE'.
43	     */
44	    default String contactPreference(Owner owner) {
45	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
46	        return hasEmail ? "EMAIL" : "PHONE";
47	    }
48	
49	    /**
50	     * The owner's region, read from the {@code <REGION>-<HASH8>} customer code assigned on
51	     * creation: the segment before the first '-'. Returns 'UNKNOWN' when no customer code has
52	     * been assigned (e.g. legacy owners predating the region-and-hash identity).
53	     */
54	    default String locality(Owner owner) {
55	        String code = owner.getCustomerCode();
56	        if (code != null) {
57	            int dash = code.indexOf('-');
58	            if (dash > 0) {
59	                return code.substring(0, dash);
60	            }
61	        }
62	        return "UNKNOWN";
63	    }
64	
65	    /**
66	     * The owner's numeric membership level, assigned on creation. It starts at 1, gains
67	     * 1 when an email address is present, and gains 1 when the owner has no namesakes
68	     * (namesakeCount is 0), capped at 3. Level 4 is reserved for tenure.
69	     */
70	    default Integer membershipLevel(Owner owner) {
71	        int level = 1;
72	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
73	        if (hasEmail) {
74	            level++;
75	        }
76	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
77	        if (noNamesakes) {
78	            level++;
79	        }
80	        return Math.min(level, 3);
81	    }
82	
83	    /**
84	     * A single Luhn check digit (0-9) computed over the digits contained in the owner's
85	     * customerCode. Returns {@code null} when the customerCode has not been assigned.
86	     */
87	    default Integer checkDigit(Owner owner) {
88	        if (owner.getCustomerCode() == null) {
89	            return null;
90	        }
91	        String s = owner.getCustomerCode();
92	        int sum = 0;
93	        boolean dbl = true;
94	        for (int i = s.length() - 1; i >= 0; i--) {
95	            char c = s.charAt(i);
96	            if (c < '0' || c > '9') {
97	                continue;
98	            }
